use crate::{jz53 as b,model::*,unit_support::*};
fn top(g:&mut Game){for _ in 0..80{if g.pending.is_some()||g.stack.is_empty(){return;}crate::jc029_tests::pass_top(g);}panic!()}
fn grave(g:&mut Game,id:&str,seat:usize)->String{let c=g.make_card(id,seat);let id=c.id.clone();g.players[seat].graveyard.push(c);id}
#[test]fn jz53_real_entry_recovers_death_character_then_generates_walker(){assert_current_serial_catalog();let mut g=game();fund(&mut g,0,"BQ092",4);let corpse=grave(&mut g,"CQ27",0);let id=held(&mut g,b::ID,0);act(&mut g,0,Action{card_id:Some(id),region:Some(0),..Action::new("deploy")});top(&mut g);assert_eq!(g.pending.as_ref().unwrap().choice.options[0].id,corpse);choose(&mut g,vec![corpse]);top(&mut g);assert!(g.players[0].hand.iter().any(|c|c.definition=="CQ27"));assert!(g.pending.as_ref().unwrap().choice.options.iter().any(|o|o.id=="region:0"));choose(&mut g,vec!["region:0".into()]);top(&mut g);assert!(g.regions[0].cards.iter().any(|c|c.definition=="TK001"&&c.exhausted));restore(&mut g);}
#[test]fn jz53_observes_actual_grave_return_not_board_return_or_foreign_grave(){let mut g=game();field(&mut g,b::ID,0);let id=grave(&mut g,"JC125",0);return_zone(&mut g,&id);g.drive().unwrap();assert!(g.pending.is_some());restore(&mut g);choose(&mut g,vec!["region:1".into()]);top(&mut g);let id=grave(&mut g,"JC125",1);return_zone(&mut g,&id);g.drive().unwrap();assert!(g.pending.is_none());let id=field(&mut g,"JC125",0);return_zone(&mut g,&id);g.drive().unwrap();assert!(g.pending.is_none());restore(&mut g);}
fn bad(g:&Game,x:&Game){assert!(Game::from_persisted(&serde_json::to_string(x).unwrap()).is_err());let mut r=crate::jc029_tests::envelope(g);r.game=x.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
fn departing()->Game{let mut g=game();field(&mut g,b::ID,0);let id=grave(&mut g,"JC125",0);return_zone(&mut g,&id);g.drive().unwrap();g}
#[test]fn jz53_noncharacter_hidden_and_foreign_controller_do_not_observe(){for mode in 0..3{let mut g=game();let id=field(&mut g,b::ID,0);if mode==0{g.board_mut(&id).unwrap().face_down=true;}else if mode==1{g.board_mut(&id).unwrap().controller=1;}let id=grave(&mut g,if mode==2{"BQ088"}else{"JC125"},0);return_zone(&mut g,&id);g.drive().unwrap();assert!(g.pending.is_none());restore(&mut g);}}
#[test]fn jz53_entry_target_is_own_death_character_not_spell_other_domain_or_ally(){let mut g=game();let id=field(&mut g,b::ID,0);let good=grave(&mut g,"CQ27",0);grave(&mut g,"BQ088",0);grave(&mut g,"JC125",0);grave(&mut g,"CQ27",1);let c=g.board(&id).unwrap().1.clone();g.emit_event(0,g.source_snapshot(&c,Some(0)),crate::rules::Event::Enter);g.drive().unwrap();assert_eq!(g.pending.as_ref().unwrap().choice.options.iter().map(|o|o.id.clone()).collect::<Vec<_>>(),vec![good]);choose(&mut g,vec![]);assert!(g.pending.is_none());restore(&mut g);}
#[test]fn jz53_departure_pending_rejects_mutated_observation_and_duplicate_carrier(){let g=departing();for n in 0..5{let mut x=g.clone();let p=x.pending.as_mut().unwrap();match n{0=>p.choice.options.clear(),1=>p.seat=1,_=>{let ChoiceResolution::Declare{declaration:d,..}=&mut p.resolution else{panic!()};if n==4{x.effects.push_back(Effect::Declare{declaration:d.clone()});}else{let crate::rules::Op::JZ53Generate{departure:Some(o)}=&mut d.ability.ops[0]else{panic!()};if n==2{o.owner=1;}else{o.card.definition="BQ088".into();}}}}bad(&g,&x);}}
#[test]fn jz53_wrong_seat_extra_payload_and_duplicate_choice_rejected(){let mut g=departing();let p=g.pending.as_ref().unwrap();let a=Action{choice_id:Some(p.choice.id.clone()),selected:Some(vec!["region:0".into()]),..Action::new("choose")};reject(&mut g,1,a.clone());reject(&mut g,0,Action{amount:Some(9),..a.clone()});act(&mut g,0,a.clone());reject(&mut g,0,a);top(&mut g);assert_eq!(g.regions[0].cards.iter().filter(|c|c.definition=="TK001").count(),1);}
#[test]fn jz53_region_replaced_after_declaration_cancels_and_source_departure_does_not(){for replaced in [false,true]{let mut g=departing();choose(&mut g,vec!["region:1".into()]);let source=g.regions[0].cards.iter().find(|c|c.definition==b::ID).unwrap().id.clone();g.return_hand(&source);if replaced{g.regions[1].card=g.make_card("DQJC115",0);}top(&mut g);assert_eq!(g.regions[1].cards.iter().filter(|c|c.definition=="TK001").count(),usize::from(!replaced));restore(&mut g);}}
#[test]fn jz53_actual_cq27_grave_return_does_not_observe_itself_but_notifies_existing_source(){let mut g=game();field(&mut g,b::ID,0);let id=grave(&mut g,"CQ27",0);let ids=(0..3).map(|_|field(&mut g,"JC125",0)).collect();act(&mut g,0,Action{card_id:Some(id),ability_id:Some(crate::cq27::GRAVE.into()),cost_selected:Some(ids),..Action::new("activate")});top(&mut g);assert!(g.pending.is_some());choose(&mut g,vec!["region:2".into()]);top(&mut g);assert_eq!(g.regions[2].cards.iter().filter(|c|c.definition=="TK001").count(),1);restore(&mut g);}
#[test]fn jz53_sealing_boundary_observes_each_character_once(){let mut g=game();field(&mut g,b::ID,0);let ids=(0..3).map(|_|grave(&mut g,"JC125",0)).collect::<Vec<_>>();let h=field(&mut g,"JC125",0);for id in &ids{let i=g.players[0].graveyard.iter().position(|c|&c.id==id).unwrap();let c=g.take_grave_observed(0,i);g.seal_card_on_valid_host(c,0,&h);}g.drive().unwrap();for _ in 0..3{restore(&mut g);choose(&mut g,vec!["region:0".into()]);top(&mut g);}assert!(g.pending.is_none());assert_eq!(g.regions[0].cards.iter().filter(|c|c.definition=="TK001").count(),3);assert_eq!(g.sealed_cards.len(),3);restore(&mut g);}
use crate::{catalog,abi112_review_play_tests::Trace};
fn duplicate(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.outcome,"rejected");assert!(!d.changed&&d.journal.is_empty());assert_eq!(d.state,s["expected"]["state"]);s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn construct(seed:u64)->Game{use crate::deck;let mut d=deck::preset("watchers").unwrap();d.id="jz53-natural".into();d.society_id=None;d.core_card_id=None;d.cards=[(b::ID,3),("CQ27",3),("BQ088",3),("BQ092",3),("JC125",38)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();for c in &mut cards{if [b::ID,"CQ27","BQ088"].contains(&c.id.as_str()){c.supported=true;}}let d=deck::validate_with_cards(d,&cards).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("jz53".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}
fn initial_choice(g:&Game)->Vec<String>{let p=g.pending.as_ref().unwrap();let mut opts=p.choice.options.iter().collect::<Vec<_>>();opts.sort_by_key(|o|g.players[p.seat].hand.iter().any(|c|c.id==o.id&&[b::ID,"BQ088","BQ092"].contains(&c.definition.as_str())));opts.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect()}
fn natural()->serde_json::Value{let seed=(1..10000).find(|seed|{let mut g=construct(*seed);for _ in 0..40{if g.pending.is_some(){let ids=initial_choice(&g);choose(&mut g,ids);}else if g.legal_actions(0).iter().any(|a|a.action.kind=="asset"){break;}else{let Some(s)=(0..4).find(|s|g.legal_actions(*s).iter().any(|a|a.action.kind=="pass"))else{return false;};g.apply(s,Action::new("pass")).unwrap();}}[b::ID,"BQ088","BQ092"].iter().all(|id|g.players[0].hand.iter().any(|c|&c.definition==id))&&g.players[0].deck.first().is_some_and(|c|c.definition=="CQ27")}).expect("natural legal seed");let g=construct(seed);let deck=g.players[0].deck_snapshot.clone().unwrap();let mut t=Trace::new_preserving_rng(g,"jz53-natural-fifty-mill-entry-recover-walker".into(),871);let mut milled=false;let mut deployed=false;let mut generated=false;for _ in 0..2200{if let Some(p)=t.room.game.pending.clone(){if matches!(&p.resolution,ChoiceResolution::Forecast{..}|ChoiceResolution::Frame{choice:FrameChoice::Forecast{..},..}){let top=p.choice.options.iter().map(|o|o.id.clone()).collect();t.action(p.seat,Action{choice_id:Some(p.choice.id),top:Some(top),bottom:Some(vec![]),..Action::new("choose")});continue;}let ids=if let ChoiceResolution::Declare{declaration:d,..}=&p.resolution{if d.ability.key==b::ENTER{vec![p.choice.options.iter().find(|o|t.room.game.players[0].graveyard.iter().any(|c|c.id==o.id&&c.definition=="CQ27")).unwrap().id.clone()]}else if d.ability.key==b::LEAVE{generated=true;vec!["region:0".into()]}else{initial_choice(&t.room.game)}}else{initial_choice(&t.room.game)};t.choose(ids);continue;}if generated&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}if !t.room.game.stack.is_empty(){t.pass();continue;}let g=&t.room.game;let legal=g.legal_actions(0);let a=if deployed{None}else if !milled&&!g.players[0].assets.is_empty(){legal.iter().find(|a|a.action.ability_id.as_deref()==Some(crate::bq088::KEY)&&a.action.option.as_deref()==Some("generate"))}else if milled&&g.players[0].assets.len()>=4&&g.players[0].assets.iter().filter(|c|catalog::card(&c.definition).color=="黑").count()>=2{legal.iter().find(|a|a.action.kind=="deploy"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition==b::ID)))}else{legal.iter().filter(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition!=b::ID&&(milled||c.definition=="BQ092")))).min_by_key(|a|g.players[0].hand.iter().find(|c|Some(&c.id)==a.action.card_id.as_ref()).map_or(true,|c|catalog::card(&c.definition).color!="黑"))};if let Some(a)=a{if a.action.ability_id.as_deref()==Some(crate::bq088::KEY){milled=true;}if a.action.kind=="deploy"{deployed=true;}t.action(0,a.action.clone());}else{t.pass();}}assert!(milled&&deployed&&generated,"seed={seed} milled={milled} deployed={deployed} generated={generated} turn={} assets={:?} hand={:?} grave={:?}",t.room.game.turn,t.room.game.players[0].assets.iter().map(|c|&c.definition).collect::<Vec<_>>(),t.room.game.players[0].hand.iter().map(|c|&c.definition).collect::<Vec<_>>(),t.room.game.players[0].graveyard.iter().map(|c|&c.definition).collect::<Vec<_>>());assert!(t.room.game.players[0].hand.iter().any(|c|c.definition=="CQ27"));let mut v=t.value();v["construction"]=serde_json::json!({"seed":seed,"deck":deck,"ordinaryCards":50,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true});duplicate(v)}
fn prepared()->serde_json::Value{let mut g=game();field(&mut g,b::ID,0);fund(&mut g,0,"BQ092",1);let h=g.make_card("BQ092",0);let host=h.id.clone();g.attachments.push(Attachment{card:h,host_id:g.regions[0].card.id.clone()});let corpse=grave(&mut g,"XQ46",0);let id=held(&mut g,"BQ088",0);let mut t=Trace::new_preserving_rng(g,"jz53-prepared-real-bq088-seal".into(),872);t.action(0,Action{card_id:Some(id),ability_id:Some(crate::bq088::KEY.into()),option:Some("seal".into()),region:Some(0),target_id:Some(host),..Action::new("play")});let mut observed=false;for _ in 0..60{if let Some(p)=t.room.game.pending.clone(){let ids=if p.choice.kind=="bq088-seal"{vec![corpse.clone()]}else if matches!(&p.resolution,ChoiceResolution::Declare{declaration:d,..}if d.ability.key==b::LEAVE){observed=true;vec!["region:1".into()]}else{vec![]};t.choose(ids);}else if !t.room.game.stack.is_empty(){t.pass();}else{break;}}assert!(observed);assert_eq!(t.room.game.regions[1].cards.iter().filter(|c|c.definition=="TK001").count(),1);duplicate(t.value())}
#[test]fn jz53_native_natural_and_real_seal_export(){let cases=vec![natural(),prepared()];let mut binding=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(n,bytes)in[("rust-game/src/jz53.rs",include_bytes!("jz53.rs").as_slice()),("rust-game/src/jz53_tests.rs",include_bytes!("jz53_tests.rs").as_slice())]{binding["files"][n]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}if let Ok(p)=std::env::var("JZ53_NATIVE_OUT"){std::fs::write(p,serde_json::to_vec(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":binding,"cases":cases})).unwrap()).unwrap();}}

fn return_zone(g:&mut Game,id:&str){if let Some((seat,i))=g.players.iter().enumerate().find_map(|(seat,p)|p.graveyard.iter().position(|c|c.id==id).map(|i|(seat,i))){let c=g.take_grave_observed(seat,i);let c=g.reset_zone_card(c);g.players[seat].hand.push(c);}else{g.return_hand(id);}}
